VALUES ('698f48be4ba0affafbf153db', 'SVB card payoff + closure', '640643a3fd8f3ca308d9318e', '640643a3fd8f3ca308d93195', 'From the call with SVB today: once the payoff from the data deal posts, they close the card on Feb 20. Any charge after that is declined. Anything we keep that will charge the card again while we still need it has to move to Arthur''s KubLLC card or one of our personal cards by end of day Feb 19. Whatever we''re cancelling can stay on the card until it ends.', 2.0, false, NULL, false, '[]', '[]', 456, NULL, NULL, 'https://PERSON_6092_TRELLO_USERNAME.com/c/FR0HGGrp/456-svb-card-payoff-closure', '2026-02-13T15:52:30Z', NULL, '{"attachments": 0, "attachmentsByType": {"trello": {"board": 0, "card": 0}}, "checkItems": 0, "checkItemsChecked": 0, "checkItemsEarliestDue": null, "comments": 0, "description": true, "due": null, "dueComplete": false, "externalSource": null, "fogbugz": "", "lastUpdatedByAi": false, "location": false, "maliciousAttachments": 0, "start": null, "votes": 0}');
