VALUES ('arthur.blake@harmonygames.co/<CAS-TQ8VVR3eSFKWcX8_qppbQEILXpnhEbstiMuR@mail.gmail.com>', 'arthur.blake@harmonygames.co/1856945900225226172', 'arthur.blake@harmonygames.co', '["INBOX", "IMPORTANT", "CATEGORY_PERSONAL"]', 'Leonard, As promised on our call, here is the checklist we run on an assignment for the benefit of creditors: 1. Cancel every subscription r', 1770921612000, '2026-02-12T18:40:12Z', 1284, 'Wind-down checklist – Harmony Games', 'PERSON_0728_EMAIL', 'PERSON_0728_NAME', '["leonard hayes <leonard.hayes@harmonygames.co>"]', '["robert <robert@harmonygames.co>", "arthur blake <arthur.blake@harmonygames.co>"]', '[]', '[]', E'Leonard,\n\nAs promised on our call, here is the checklist we run on an assignment for the benefit of creditors:\n1. Cancel every subscription right away except payroll and accounting.\n2. Export whatever records you need before you cancel.\n3. Close the company cards last, once nothing bills them.\n\nIf you decide to engage us we would run this for you.\n\nBest,\nSherwood Partners', NULL, '[{"name": "Message-ID", "value": "<CAS-TQ8VVR3eSFKWcX8_qppbQEILXpnhEbstiMuR@mail.gmail.com>"}, {"name": "Date", "value": "Thu, 12 Feb 2026 18:40:12 +0000"}, {"name": "Subject", "value": "Wind-down checklist – Harmony Games"}, {"name": "From", "value": "PERSON_0728_NAME <PERSON_0728_EMAIL>"}, {"name": "To", "value": "leonard hayes <leonard.hayes@harmonygames.co>"}, {"name": "Cc", "value": "robert <robert@harmonygames.co>, arthur blake <arthur.blake@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
